// --- ICON HELPER FUNCTION ---
// (No changes here, just including for completeness of the file replacement)
export function getIcon(category, p, isFeatured = false) {
    const title = p.title || "";
    const text = p.text || "";
    const c = isFeatured ? "text-stone-700" : "text-stone-300";
    let content = icons.default;

    // Keyword Matching
    if (title.includes("مورچه") || text.includes("مورچه")) content = icons.ants;
    else if (title.includes("شبکه") || title.includes("شطرنج") || title.includes("دومینو")) content = icons.grid;
    else if (title.includes("سکه")) content = icons.coins;
    else if (title.includes("گراف") || title.includes("دوستی")) content = icons.graph;
    else if (title.includes("زندانی") || title.includes("جعبه") || title.includes("اتاق")) content = icons.prison;
    else if (title.includes("سم") || title.includes("لیوان") || title.includes("شراب")) content = icons.potion;
    else if (category === "Geometry" || title.includes("مثلث") || title.includes("کره")) content = icons.geo;
    else if (category === "Logic") content = icons.logic;

    return `<svg class="w-full h-full ${c}" viewBox="0 0 24 24" preserveAspectRatio="xMidYMid meet">${content}</svg>`;
}